insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('f637f3b3-5bda-4f6f-bbac-2a57b51812a7', 'Notify sales team of new leads', 'When a new lead is created, notify the sales team.', 'lead.created', '[]'::jsonb, '[{"type":"notify","params":{"roles":"owner,sales_rep,office_manager","title":"New lead: {{title}}","body":"{{customer}} · {{source}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('d5178a93-949a-43b1-a0b5-4b5d8fa71965', 'Estimate follow-up reminder', 'When an estimate is sent, schedule a follow-up task in 3 days.', 'estimate.sent', '[]'::jsonb, '[{"type":"schedule_follow_up","params":{"days":3,"title":"Follow up on {{number}} with {{customer}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('06cc90a7-475e-4ad3-bf13-ce586854d750', 'Create project from approved estimate', 'When an estimate is approved, automatically create the project and mark the lead won.', 'estimate.approved', '[]'::jsonb, '[{"type":"create_project","params":{}},{"type":"notify","params":{"roles":"owner,project_manager,office_manager","title":"Estimate approved: {{number}}","body":"{{customer}} · {{total}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('d7977af7-29cb-49d5-9584-9a0ed114cebf', 'Notify PM when contract signed', 'When a contract is signed, notify the project manager.', 'contract.signed', '[]'::jsonb, '[{"type":"notify","params":{"roles":"project_manager,owner","title":"Contract signed: {{name}}","body":"Ready for deposit invoice"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('33895515-4217-4fe6-b15e-b13c3b2b7cf9', 'Deposit received → advance project', 'When a deposit is received, move the project to Deposit Received.', 'deposit.received', '[]'::jsonb, '[{"type":"set_project_stage","params":{"stage":"Deposit Received"}},{"type":"notify","params":{"roles":"project_manager,office_manager","title":"Deposit received: {{project}}","body":"{{amount}} via {{method}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('208c3d6f-d1c1-4b94-b8ec-31e5d9a556f8', 'Materials ordered → update timeline', 'When a purchase order is placed for a project, set the project to Materials Ordered.', 'po.ordered', '[]'::jsonb, '[{"type":"set_project_stage","params":{"stage":"Materials Ordered","only_if_before":true}},{"type":"log_activity","params":{"subject":"Materials ordered ({{number}})"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('68e8ccd8-06f4-4e39-a9a4-3733c518abfe', 'Materials received → update project', 'When a purchase order is fully received, set the project to Materials Delivered.', 'po.received', '[]'::jsonb, '[{"type":"set_project_stage","params":{"stage":"Materials Delivered","only_if_before":true}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('a3823497-0ad2-4cd5-9843-466dc1439b64', 'Installation reminder to customer', 'Before a scheduled installation, notify the customer (email/SMS integration ready).', 'event.upcoming_installation', '[]'::jsonb, '[{"type":"send_email","params":{"to":"customer","subject":"Your installation is scheduled for {{date}}","body":"Hi {{customer}}, our crew arrives {{date}}."}},{"type":"log_activity","params":{"subject":"Installation reminder sent for {{date}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('e8918296-9cc7-4910-8608-b20a536b4b02', 'Final invoice reminder on completion', 'When a project is completed, create the final invoice reminder.', 'project.completed', '[]'::jsonb, '[{"type":"create_final_invoice","params":{}},{"type":"notify","params":{"roles":"office_manager,owner","title":"Final invoice ready: {{name}}","body":"Project completed — send the final invoice."}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('a66b2cf9-9725-4a3f-8314-81e7f2157e67', 'Overdue invoice alert', 'When an invoice becomes overdue, notify the office.', 'invoice.overdue', '[]'::jsonb, '[{"type":"notify","params":{"roles":"office_manager,owner","title":"Invoice overdue: {{number}}","body":"{{customer}} · balance {{balance}}","kind":"danger"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('a4eef5f9-84e6-4e12-af67-39240caeb8b8', 'Change order approved', 'When a customer approves a change order, notify the PM.', 'change_order.approved', '[]'::jsonb, '[{"type":"notify","params":{"roles":"project_manager,owner","title":"Change order approved: {{number}}","body":"{{amount}} added to contract"}}]'::jsonb, true, 0, null);
